# enumerate exact covers of test cells by 2x2 squares and 3-cell Ls
rows=['.##.##.','######.','.##.#..','..###..','.......','.......','.......']
S={(r,c) for r,row in enumerate(rows) for c,ch in enumerate(row) if ch=='#'}
placements=[]
for r in range(6):
 for c in range(6):
  cells={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if cells<=S:
   placements.append(('square',r,c,cells))
  for miss in cells:
   p=cells-{miss}
   if p<=S: placements.append((f'L miss {miss}',r,c,p))
# exact cover all; pieces 2x2 size 3 or4
covers=[]
def rec(rem, chosen):
 if not rem:
  covers.append(chosen); return
 x=min(rem)
 for p in placements:
  if x in p[3] and p[3]<=rem:
   rec(rem-p[3],chosen+[p])
rec(S,[])
len(S),len(covers), [[(p[0],p[1],p[2]) for p in cov] for cov in covers[:20]]
